                                </div>
                                <div class="w-full h-3.5 rounded-full overflow-hidden progress-bar theme-transition relative">
                                    <!-- CORE FIX: Directly apply Tailwind color class -->
                                    <div class="h-full rounded-full bg-red-400 theme-transition" style="width: ${depravityValue}%"></div>
                                    <div class="absolute inset-0 flex items-center justify-center text-[10px] font-bold text-white text-shadow-sm">${depravityValue}%</div>
                                </div>
                            </div>
                        </div>
                        <details class="text-sm text-[var(--card-text-subtle)] theme-transition mt-3 pt-3 border-t border-dashed border-[var(--card-border)] group" open>
                            <summary class="cursor-pointer list-none flex justify-between items-center font-bold text-[var(--card-text)]">详细状态 <i class="fa fa-chevron-down text-xs transition-transform duration-300 group-open:rotate-180"></i></summary>
                            <div class="mt-2 space-y-1.5">
