                                    .filter(key => !['名字', '淫堕值'].includes(key))
                                    .map(key => {
                                        const iconMap = {'行动':'📝', '穿搭':'👗', '小穴':'🌸', '胸部':'🍒', '肛门':'🍑'};
                                        const icon = iconMap[key] || '🔹';
                                        return `<p><strong class="font-bold">${icon} ${key}:</strong> ${char[key].replace(/[\p{Emoji}\p{Emoji_Presentation}\p{Emoji_Modifier}\p{Emoji_Modifier_Base}\p{Emoji_Component}]/gu, '').trim()}</p>`;
                                    })
                                    .join('')
                                }
                            </div>
                         </details>
                    `;
                } else {
                     detailsHtml = `
                        <div class="space-y-1.5 text-sm">
                        ${Object.keys(char)
                            .filter(key => key !== '名字')
                            .map(key => {
                                const iconMap = {'行动':'📝', '肉棒':'🦴'};
                                const icon = iconMap[key] || '🔹';
                                return `<p><strong class="font-bold text-[var(--card-text)] theme-transition">${icon} ${key}:</strong> <span class="text-[var(--card-text-subtle)]">${(char[key] || '无').replace(/[\p{Emoji}\p{Emoji_Presentation}\p{Emoji_Modifier}\p{Emoji_Modifier_Base}\p{Emoji_Component}]/gu, '').trim()}</span></p>`;
                            })
                            .join('')
                        }
                        </div>`;
                }

                const card = `
                    <div class="bg-[var(--card-bg)] border border-[var(--card-border)] shadow-lg shadow-[var(--theme-shadow)] rounded-3xl p-4 card-hover theme-transition">
                        <h4 class="text-lg font-extrabold text-[var(--card-text)] mb-3 theme-transition">${emoji} ${cleanName}</h4>
                        ${detailsHtml}
                    </div>`;
                charactersContainer.innerHTML += card;
            });

             // --- Render Off-Screen Characters ---
            const offScreenContainer = document.getElementById('off-screen-container');
            offScreenContainer.innerHTML = '';
            (statusData['远程观察'] || []).forEach(item => {
                 const char = item['成员'];
                 const emoji = (char['名字'].match(/[\u{1F600}-\u{1F6FF}]/gu) || ['👤'])[0];
                 const cleanName = char['名字'].replace(/[\u{1F600}-\u{1F6FF}]/gu, '').trim();
                 const depravityMatch = (char['淫堕值'] || '').match(/(\d+)\/100/);
                 const depravityValue = depravityMatch ? depravityMatch[1] : 0;
                 const depravityText = char['淫堕值'].replace('🔥 ','');

                 const itemHtml = `
                    <div class="bg-[var(--off-screen-bg)] border border-[var(--off-screen-border)] rounded-lg px-3 py-2 text-xs theme-transition">
                        <div class="flex justify-between items-center text-[var(--off-screen-text)] font-semibold theme-transition mb-1.5">
