                const li = document.createElement('li');
                li.className = 'bg-[var(--card-bg)] border border-[var(--option-border)] text-[var(--option-text)] rounded-xl p-3 text-sm font-semibold cursor-pointer card-hover theme-transition hover:border-[var(--text-main)]';
                li.innerHTML = opt;
                li.addEventListener('click', () => triggerQuickReply(opt));
