            const styleSheet = document.createElement("style");
            styleSheet.innerText = `.text-shadow-sm { text-shadow: 0px 1px 2px rgba(0, 0, 0, 0.6); }`;
            document.head.appendChild(styleSheet);
        });
    </script>
</body>
</html>
